import { i18n } from '@osd/i18n';
import { FeatureCatalogueCategory } from '../../home/public';
export class ConsoleUIPlugin {
  setup({
    notifications,
    getStartServices,
    http
  }, {
    devTools,
    home,
    usageCollection
  }) {
    if (home) {
      home.featureCatalogue.register({
        id: 'console',
        title: i18n.translate('console.devToolsTitle', {
          defaultMessage: 'Interact with the OpenSearch API'
        }),
        description: i18n.translate('console.devToolsDescription', {
          defaultMessage: 'Skip cURL and use a JSON interface to work with your data in Console.'
        }),
        icon: 'consoleApp',
        path: '/app/dev_tools#/console',
        showOnHomePage: false,
        category: FeatureCatalogueCategory.ADMIN
      });
    }
    devTools.register({
      id: 'console',
      order: 1,
      title: i18n.translate('console.consoleDisplayName', {
        defaultMessage: 'Console'
      }),
      enableRouting: false,
      mount: async ({
        element,
        dataSourceId
      }) => {
        const [core] = await getStartServices();
        const {
          i18n: {
            Context: I18nContext
          },
          docLinks: {
            DOC_LINK_VERSION
          },
          uiSettings
        } = core;
        const {
          renderApp
        } = await import('./application');
        return renderApp({
          http,
          docLinkVersion: DOC_LINK_VERSION,
          I18nContext,
          notifications,
          usageCollection,
          element,
          dataSourceId,
          uiSettings
        });
      }
    });
  }
  start() {}
}